file.content:
:root {
  color-scheme: light dark;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  line-height: 1.5;
}

body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: Canvas;
  color: CanvasText;
}

main {
  padding: 2rem;
  text-align: center;
}

p {
  margin: 0;
  color: #9ca3af;
}

