:root {
  --cream: #fbf5ea;
  --flour: #f4ead8;
  --crust: #b8652a;
  --crust-dark: #8f4a1a;
  --cocoa: #3b2418;
  --ink: #2c1d14;
  --muted: #7a6656;
  --line: #e6d7bf;
  --berry: #8e2f3c;
  --radius: 20px;
  --serif: "Fraunces", Georgia, "Times New Roman", serif;
  --sans: "Inter", system-ui, -apple-system, "Segoe UI", sans-serif;

  color-scheme: light;
  font-family: var(--sans);
  line-height: 1.6;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  background: var(--cream);
  color: var(--ink);
}

h1, h2, h3 {
  font-family: var(--serif);
  line-height: 1.1;
  margin: 0;
  color: var(--cocoa);
}

p { margin: 0; }
a { color: inherit; }

.container {
  width: min(1200px, 100% - 48px);
  margin-inline: auto;
}

.eyebrow {
  font-size: 0.8rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--crust);
  margin-bottom: 14px;
}

.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 26px;
  border-radius: 999px;
  border: 2px solid var(--crust);
  background: var(--crust);
  color: var(--cream);
  font: 600 1rem var(--sans);
  text-decoration: none;
  cursor: pointer;
  transition: background 0.2s, transform 0.2s;
}
.btn:hover { background: var(--crust-dark); border-color: var(--crust-dark); transform: translateY(-1px); }
.btn-ghost { background: transparent; color: var(--crust-dark); }
.btn-ghost:hover { background: var(--flour); color: var(--crust-dark); border-color: var(--crust-dark); }
.btn-small { padding: 9px 18px; font-size: 0.9rem; }

/* Header */
.site-header {
  position: sticky;
  top: 0;
  z-index: 10;
  background: rgb(251 245 234 / 0.9);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--line);
}
.nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 76px;
}
.logo {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font: 700 1.35rem var(--serif);
  color: var(--cocoa);
  text-decoration: none;
}
.logo-mark { width: 32px; height: 32px; color: var(--crust); display: inline-flex; }
.logo-mark svg { width: 100%; height: 100%; }
.nav-links { display: flex; align-items: center; gap: 32px; }
.nav-links a:not(.btn) {
  text-decoration: none;
  font-weight: 500;
  color: var(--muted);
}
.nav-links a:not(.btn):hover { color: var(--cocoa); }

/* Hero */
.hero { padding: 88px 0 104px; overflow: hidden; }
.hero-grid {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 64px;
  align-items: center;
}
.hero h1 {
  font-size: clamp(2.8rem, 5.5vw, 4.8rem);
  font-weight: 600;
  letter-spacing: -0.02em;
}
.hero h1 em { font-style: italic; color: var(--crust); font-weight: 400; }
.lede {
  margin-top: 24px;
  font-size: 1.2rem;
  color: var(--muted);
  max-width: 34ch;
}
.hero-actions { display: flex; flex-wrap: wrap; gap: 14px; margin-top: 36px; }
.hero-facts {
  list-style: none;
  padding: 28px 0 0;
  margin: 44px 0 0;
  border-top: 1px solid var(--line);
  display: flex;
  gap: 40px;
  color: var(--muted);
  font-size: 0.92rem;
}
.hero-facts strong {
  display: block;
  font: 600 1.5rem var(--serif);
  color: var(--cocoa);
}

.hero-art { position: relative; aspect-ratio: 1; }
.hero-plate {
  position: absolute;
  inset: 6%;
  border-radius: 50%;
  background:
    radial-gradient(circle at 50% 45%, #fff8ec 0 52%, transparent 53%),
    repeating-conic-gradient(from 0deg, #efdcbc 0 6deg, #f6e8d0 6deg 12deg);
  box-shadow: 0 30px 60px -30px rgb(80 40 10 / 0.35), inset 0 0 0 14px #f6e8d0;
  display: grid;
  place-items: center;
}
.loaf { width: 70%; transform: rotate(-6deg); }
.badge {
  position: absolute;
  background: #fff;
  border-radius: 16px;
  padding: 14px 18px;
  box-shadow: 0 14px 30px -14px rgb(60 30 10 / 0.35);
  font-size: 0.88rem;
  color: var(--muted);
  display: flex;
  flex-direction: column;
}
.badge-top {
  top: 4%; right: 0;
  background: var(--berry);
  color: #f8dfe2;
  border-radius: 50%;
  width: 120px; height: 120px;
  align-items: center; justify-content: center;
  text-align: center;
  transform: rotate(10deg);
}
.badge-big { font: 700 1.6rem var(--serif); color: #fff; line-height: 1; }
.badge-bottom { bottom: 6%; left: -2%; max-width: 240px; }
.stars { color: #d99a2b; letter-spacing: 2px; }

/* Sections */
.section { padding: 104px 0; }
.section-head { max-width: 560px; margin-bottom: 56px; }
.section-head h2, .story-copy h2, .visit-card h2, .cta h2 {
  font-size: clamp(2.2rem, 3.6vw, 3.2rem);
  font-weight: 600;
  letter-spacing: -0.015em;
}
.section-head p:last-child { margin-top: 16px; color: var(--muted); font-size: 1.1rem; }

/* Bakes */
.bake-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.bake-card {
  background: #fffaf2;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  transition: transform 0.25s, box-shadow 0.25s;
}
.bake-card:hover { transform: translateY(-4px); box-shadow: 0 20px 40px -24px rgb(80 40 10 / 0.4); }
.bake-art { aspect-ratio: 4 / 3; display: grid; place-items: center; }
.bake-art svg { width: 62%; }
.tone-wheat  { background: #f1dfc0; }
.tone-butter { background: #f6e5b8; }
.tone-berry  { background: #efd2d0; }
.tone-cocoa  { background: #e8d6c4; }
.bake-body { padding: 22px 22px 26px; }
.bake-title { display: flex; justify-content: space-between; align-items: baseline; gap: 12px; }
.bake-title h3 { font-size: 1.25rem; font-weight: 600; }
.price { font: 600 1.1rem var(--serif); color: var(--crust); }
.bake-body p { margin-top: 10px; color: var(--muted); font-size: 0.95rem; }
.tag {
  display: inline-block;
  margin-top: 16px;
  padding: 4px 12px;
  border-radius: 999px;
  background: var(--flour);
  color: var(--crust-dark);
  font-size: 0.78rem;
  font-weight: 600;
}

/* Story */
.section-story { background: var(--flour); }
.story-grid {
  display: grid;
  grid-template-columns: 1fr 1.2fr;
  gap: 80px;
  align-items: center;
}
.story-photo {
  aspect-ratio: 4 / 5;
  border-radius: 200px 200px var(--radius) var(--radius);
  background:
    radial-gradient(circle at 30% 20%, rgb(255 255 255 / 0.18), transparent 50%),
    linear-gradient(160deg, #b8652a, #6e3714);
  color: #f6e2c6;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  font-size: 0.85rem;
  box-shadow: 0 30px 60px -30px rgb(80 40 10 / 0.5);
}
.story-photo strong {
  font: 600 5rem var(--serif);
  letter-spacing: -0.02em;
  color: #fff4e3;
  line-height: 1.1;
}
.story-copy > p:not(.eyebrow) { margin-top: 22px; font-size: 1.1rem; color: var(--muted); }
.values {
  list-style: none;
  padding: 0;
  margin: 40px 0 0;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.values li { border-top: 2px solid var(--crust); padding-top: 16px; }
.values h3 { font-size: 1.1rem; font-weight: 600; }
.values p { margin-top: 6px; font-size: 0.92rem; color: var(--muted); }

/* Visit */
.visit-grid {
  display: grid;
  grid-template-columns: 1fr 1.2fr;
  gap: 32px;
  align-items: stretch;
}
.visit-card {
  background: #fffaf2;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 48px;
}
.hours { margin: 32px 0 0; }
.hours div {
  display: flex;
  justify-content: space-between;
  padding: 14px 0;
  border-bottom: 1px dashed var(--line);
}
.hours dt { font-weight: 600; color: var(--cocoa); }
.hours dd { margin: 0; color: var(--muted); }
address {
  font-style: normal;
  margin-top: 28px;
  font: 600 1.2rem/1.5 var(--serif);
  color: var(--cocoa);
}
.small { margin-top: 12px; font-size: 0.9rem; color: var(--muted); }

.map {
  position: relative;
  border-radius: var(--radius);
  overflow: hidden;
  min-height: 420px;
  background:
    linear-gradient(90deg, rgb(184 101 42 / 0.06) 1px, transparent 1px) 0 0 / 40px 40px,
    linear-gradient(rgb(184 101 42 / 0.06) 1px, transparent 1px) 0 0 / 40px 40px,
    #efe3cc;
  border: 1px solid var(--line);
}
.map-road { position: absolute; background: #fffaf2; box-shadow: 0 0 0 1px var(--line); }
.road-h { left: 0; right: 0; top: 56%; height: 34px; }
.road-v { top: 0; bottom: 0; left: 38%; width: 28px; }
.map-label {
  position: absolute;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted);
}
.label-h { top: calc(56% + 8px); right: 24px; }
.label-v { left: calc(38% + 36px); top: 20px; }
.map-pin {
  position: absolute;
  left: 38%;
  top: 56%;
  transform: translate(-50%, -100%);
  display: flex;
  flex-direction: column;
  align-items: center;
}
.map-pin span {
  background: var(--cocoa);
  color: var(--cream);
  font: 600 0.95rem var(--serif);
  padding: 10px 16px;
  border-radius: 12px;
  white-space: nowrap;
  box-shadow: 0 12px 24px -10px rgb(40 20 10 / 0.5);
}
.map-pin::after {
  content: "";
  width: 16px; height: 16px;
  margin-top: -8px;
  background: var(--cocoa);
  transform: rotate(45deg);
  border-radius: 2px;
}

/* CTA */
#order { padding-top: 0; }
.cta {
  background: var(--cocoa);
  border-radius: 28px;
  padding: 64px;
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: 48px;
  align-items: center;
  color: #e9d6bf;
  position: relative;
  overflow: hidden;
}
.cta::before {
  content: "";
  position: absolute;
  width: 360px; height: 360px;
  right: -120px; top: -160px;
  border-radius: 50%;
  background: radial-gradient(circle, rgb(184 101 42 / 0.45), transparent 70%);
}
.cta h2 { color: var(--cream); }
.cta p { margin-top: 14px; font-size: 1.1rem; }
.cta-form { display: flex; flex-wrap: wrap; gap: 12px; position: relative; }
.cta-form input {
  flex: 1 1 220px;
  padding: 14px 20px;
  border-radius: 999px;
  border: 2px solid rgb(251 245 234 / 0.2);
  background: rgb(251 245 234 / 0.08);
  color: var(--cream);
  font: 1rem var(--sans);
}
.cta-form input::placeholder { color: rgb(233 214 191 / 0.6); }
.cta-form input:focus { outline: none; border-color: var(--crust); }
.form-note { display: none; width: 100%; font-size: 0.95rem; color: #f3c58f; }
.cta-form.sent .form-note { display: block; }

/* Footer */
.site-footer { border-top: 1px solid var(--line); padding: 36px 0; color: var(--muted); font-size: 0.9rem; }
.footer-grid { display: flex; justify-content: space-between; align-items: center; gap: 24px; flex-wrap: wrap; }
.site-footer .logo { font-size: 1.1rem; }

/* Responsive */
@media (max-width: 980px) {
  .hero-grid, .story-grid, .visit-grid, .cta { grid-template-columns: 1fr; }
  .hero-art { max-width: 460px; margin-inline: auto; width: 100%; }
  .bake-grid { grid-template-columns: repeat(2, 1fr); }
  .story-art { max-width: 360px; }
  .cta { padding: 44px 32px; }
}
@media (max-width: 640px) {
  .nav-links a:not(.btn) { display: none; }
  .hero { padding: 56px 0 72px; }
  .section { padding: 72px 0; }
  .bake-grid, .values { grid-template-columns: 1fr; }
  .hero-facts { gap: 24px; flex-wrap: wrap; }
  .visit-card { padding: 32px; }
}

